\section*{Question 6}

A function \(f\) has derivatives of all orders at \(x=0\). Let \(P_{n}(x)\) denote the \(n\) th-degree Taylor polynomial for \(f\) about \(x=0\).
\begin{itemize}
\item[(a)] It is known that \(f(0)=-4\) and that \(P_{1}\left(\frac{1}{2}\right)=-3\). Show that \(f^{\prime}(0)=2\).
\item[(b)] It is known that \(f^{\prime \prime}(0)=-\frac{2}{3}\) and \(f^{\prime \prime \prime}(0)=\frac{1}{3}\). Find \(P_{3}(x)\).
\item[(c)] The function \(h\) has first derivative given by \(h^{\prime}(x)=f(2 x)\). It is known that \(h(0)=7\). Find the third-degree Taylor polynomial for \(h\) about \(x=0\).
\item[(a)] \(P_{1}(x)=f(0)+f^{\prime}(0) x=-4+f^{\prime}(0) x\)
\[
\begin{aligned}
& P_{1}\left(\frac{1}{2}\right)=-4+f^{\prime}(0) \cdot \frac{1}{2}=-3 \\
& f^{\prime}(0) \cdot \frac{1}{2}=1 \\
& f^{\prime}(0)=2
\end{aligned}
\]
\item[(b)] \(P_{3}(x)=-4+2 x+\left(-\frac{2}{3}\right) \cdot \frac{x^{2}}{2!}+\frac{1}{3} \cdot \frac{x^{3}}{3!}\)
\[
=-4+2 x-\frac{1}{3} x^{2}+\frac{1}{18} x^{3}
\]
\item[(c)] Let \(Q_{n}(x)\) denote the Taylor polynomial of degree \(n\) for \(h\) about \(x=0\).
\[
\begin{aligned}
& h^{\prime}(x)=f(2 x) \Rightarrow Q_{3}^{\prime}(x)=-4+2(2 x)-\frac{1}{3}(2 x)^{2} \\
& Q_{3}(x)=-4 x+4 \cdot \frac{x^{2}}{2}-\frac{4}{3} \cdot \frac{x^{3}}{3}+C ; C=Q_{3}(0)=h(0)=7 \\
& Q_{3}(x)=7-4 x+2 x^{2}-\frac{4}{9} x^{3}
\end{aligned}
\]
OR
\[
\begin{aligned}
& h^{\prime}(x)=f(2 x), h^{\prime \prime}(x)=2 f^{\prime}(2 x), h^{\prime \prime \prime}(x)=4 f^{\prime \prime}(2 x) \\
& h^{\prime}(0)=f(0)=-4, h^{\prime \prime}(0)=2 f^{\prime}(0)=4, h^{\prime \prime \prime}(0)=4 f^{\prime \prime}(0)=-\frac{8}{3} \\
& Q_{3}(x)=7-4 x+4 \cdot \frac{x^{2}}{2!}-\frac{8}{3} \cdot \frac{x^{3}}{3!}=7-4 x+2 x^{2}-\frac{4}{9} x^{3}
\end{aligned}
\]
\end{itemize}
\(2:\left\{\begin{array}{l}1: \text { uses } P_{1}(x) \\ 1: \text { verifies } f^{\prime}(0)=2\end{array}\right.\)
\(3:\left\{\begin{array}{l}1: \text { first two terms } \\ 1: \text { third term } \\ 1: \text { fourth term }\end{array}\right.\)
\(4:\left\{\begin{array}{l}2: \text { applies } h^{\prime}(x)=f(2 x) \\ 1: \text { constant term } \\ 1: \text { remaining terms }\end{array}\right.\)
